import java.io.File;
import java.io.IOException;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Arrays;
import java.util.List;

public class SecureFileReading {
    // This is the corrected version of the file reading code.
    // It ensures the file path stays within the allowed directory to prevent path traversal.
    public void readFileSecure(String fileName) throws IOException {
        String baseDirectory = "/safe/directory";
        // Construct the full path using Path objects for safer handling.
        Path basePath = Paths.get(baseDirectory);
        Path requestedPath = basePath.resolve(fileName).normalize();

        // Verify that the resolved path still starts with the base directory.
        // This check effectively mitigates the path traversal vulnerability.
        if (!requestedPath.startsWith(basePath)) {
            throw new SecurityException("Access denied: file path is outside the allowed directory.");
        }

        File file = requestedPath.toFile();
        // Now it is safe to read the file content.
    }
}
